    consentItemDocumentsDesc: "பழைய மருந்துச்சீட்டு, லேப் அறிக்கை — செயற்கை நுண்ணறிவு நோயறிதல், மருந்து, சோதனை முடிவுகள் எடுக்கிறது.",
