    consentItemSummaryDesc: "உங்கள் பதில்கள் மற்றும் பதிவுகளிலிருந்து சுருக்கம் — மருத்துவர் மதிப்பாய்வு/திருத்தம் செய்யலாம். செயற்கை நுண்ணறிவு நோயறிதல் செய்யாது.",
